#include <bits/stdc++.h>
#define ll long long
using namespace std;
const ll INF = 1e12;
int n;
stack<char> st;
string c;
ll s;
int main(){
    cin >> n >> s >> c;
    for(int i = 0; i < n; i ++){
        if(c[i] == 'U'){
            if(s == 1) continue;
            if(st.size()){
                st.pop();
                continue;
            }
            s >>= 1;
        }else if(c[i] == 'L'){
            if((s << 1) > INF){
                st.push('L');
                continue;
            }
            s = s << 1;
        }else{
            if((s << 1 | 1) > INF){
                st.push('R');
                continue;
            }
            s = s << 1 | 1;
        }
    }
    cout << s << "\n";
    return 0;
}

